/* Chapter minigames. State is stored inside the active profile's story object. */
function visitGameError(u,game,reason){
 if(typeof visitRecord==='function'){visitRecord(u,'error',{topic:game==='patterns'?'pattern':game,reason});return}
 u.analytics=u.analytics&&typeof u.analytics==='object'?u.analytics:{};
 u.analytics.errors=u.analytics.errors&&typeof u.analytics.errors==='object'&&!Array.isArray(u.analytics.errors)?u.analytics.errors:{};
 u.analytics.errors[game]=(Number(u.analytics.errors[game])||0)+1;
 if(!Array.isArray(u.analytics.events))u.analytics.events=[];
 u.analytics.events.push({type:'error',game,reason,at:new Date().toISOString()});
 if(u.analytics.events.length>300)u.analytics.events.splice(0,u.analytics.events.length-300);
}
function visitFoodArt(id,phase=4){
 const done=phase>=4,chak=id==='chakchak',tuk=id==='tukmach';
 const pieces=Array.from({length:chak?22:10},(_,i)=>{const x=27+(i*17)%70,y=done?55+(i*13)%24:58+(i*11)%23;return chak?`<rect x="${x}" y="${y}" width="13" height="6" rx="3" fill="${i%2?'#d99c45':'#edc06b'}" transform="rotate(${i%3*20-20} ${x} ${y})"/>`:`<path d="M${x} ${y}q8-5 15 0t13 0" fill="none" stroke="${tuk?'#e9ca7b':'#d0a87a'}" stroke-width="${tuk?3:7}" stroke-linecap="round"/>`}).join('');
 return `<svg class="visit-food-art" viewBox="0 0 130 110" role="img" aria-label="${done?'Готовое блюдо':phase===0?'Ингредиенты для блюда':'Блюдо готовится'}"><ellipse cx="65" cy="93" rx="49" ry="8" fill="#566b3b" opacity=".12"/><path d="M16 68Q20 99 65 99t49-31Z" fill="#80a08a" stroke="#557862" stroke-width="2"/><ellipse cx="65" cy="68" rx="49" ry="19" fill="#f5dfb2" stroke="#557862" stroke-width="2"/>${phase===0?'<ellipse cx="65" cy="68" rx="23" ry="13" fill="#ebd8ac"/><path d="M50 65q12-7 27 0" fill="none" stroke="#c8ad79" stroke-width="2"/>':pieces}${phase>=2&&phase<4?'<g fill="none" stroke="#a3b3a0" stroke-width="3" stroke-linecap="round"><path d="M45 39q-8-8 0-16"/><path d="M65 35q-8-9 0-18"/><path d="M85 39q-8-8 0-16"/></g>':''}${done?'<path d="M90 49l6 5 8-12" fill="none" stroke="#75914f" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>':''}</svg>`;
}
const VISIT_BLOCK_SHAPES={domino:[[0,0],[0,1]],line:[[0,0],[0,1],[0,2]],square:[[0,0],[0,1],[1,0],[1,1]],corner:[[0,0],[1,0],[1,1]]};
function visitPatternBoard(){const board=Array(64).fill(0),gaps=[6,4,2,0,6,4];for(let row=0;row<6;row++)for(let col=0;col<8;col++)if(col<gaps[row]||col>gaps[row]+1)board[row*8+col]=row%3+1;return board}
function visitPatternState(s){
 s.patterns=s.patterns&&typeof s.patterns==='object'?s.patterns:{};const p=s.patterns;
 if(!Array.isArray(p.board)||p.board.length!==64)p.board=visitPatternBoard();else p.board=p.board.map(v=>Number.isInteger(v)&&v>=0&&v<=4?v:0);
 if(!VISIT_BLOCK_SHAPES[p.selected])p.selected='domino';p.rotation=((Math.floor(Number(p.rotation)||0)%4)+4)%4;p.ribbons=Math.min(6,Math.max(0,Math.floor(Number(p.ribbons)||0)));p.moves=Math.max(0,Math.floor(Number(p.moves)||0));
 s.outfits=s.outfits&&typeof s.outfits==='object'?s.outfits:{};
 if(p.ribbons>=3)s.outfits[0]=['body','collar','hem'];if(p.ribbons>=6)s.outfits[1]=['body','collar','hem'];
 return p;
}
function visitShapeCells(id,rotation=0){let cells=VISIT_BLOCK_SHAPES[id].map(v=>v.slice());for(let r=0;r<rotation;r++)cells=cells.map(([y,x])=>[x,-y]);const minY=Math.min(...cells.map(v=>v[0])),minX=Math.min(...cells.map(v=>v[1]));return cells.map(([y,x])=>[y-minY,x-minX])}
function visitCanPlace(board,cells,row,col){return cells.every(([dy,dx])=>row+dy<8&&col+dx<8&&row+dy>=0&&col+dx>=0&&!board[(row+dy)*8+col+dx])}
function visitAnyMove(board){return Object.keys(VISIT_BLOCK_SHAPES).some(id=>[0,1,2,3].some(rot=>{const cells=visitShapeCells(id,rot);return Array.from({length:64},(_,i)=>i).some(i=>visitCanPlace(board,cells,Math.floor(i/8),i%8))}))}
function visitShapeArt(id,rotation){const cells=visitShapeCells(id,rotation);return `<span class="visit-block-shape" style="--shape-cols:${Math.max(...cells.map(v=>v[1]))+1};--shape-rows:${Math.max(...cells.map(v=>v[0]))+1}" aria-hidden="true">${cells.map(([r,c])=>`<i style="grid-row:${r+1};grid-column:${c+1}"></i>`).join('')}</span>`}
function visitPatternCostume(which,ribbons){const count=Math.min(3,Math.max(0,ribbons-which*3)),color=which===0?'#7a9e85':'#be8b7d',pattern='v-ribbon-'+which;return `<svg class="visit-costume" viewBox="0 0 170 220" role="img" aria-label="Наряд ${which+1}: ${count} из трёх узорных полос"><defs><pattern id="${pattern}" width="16" height="16" patternUnits="userSpaceOnUse"><path d="M8 1l6 7-6 7-6-7Z" fill="none" stroke="#965e43" stroke-width="2"/><circle cx="8" cy="8" r="1.7" fill="#965e43"/></pattern></defs><path d="M56 43L31 66 14 112l24 9 20-37v113h54V84l20 37 24-9-17-46-25-23Z" fill="${color}" stroke="#5c755e" stroke-width="2"/><path d="M61 46l24 30 24-30" fill="#f3ddb2" stroke="#b89b68" stroke-width="2"/>${[0,1,2].map(i=>`<path d="M58 ${113+i*27}h54v20H58Z" fill="${count>i?'url(#'+pattern+')':'#ffffff2b'}" stroke="${count>i?'#e1bb76':'#ffffff55'}" stroke-width="2"/>`).join('')}<circle cx="85" cy="23" r="19" fill="#e7bd9d"/><path d="M65 16q20-25 40 0" fill="#72533e"/><path d="M66 198v15h14v-15m10 0v15h14v-15" fill="#687f80"/></svg>`}
function renderVisitPatterns(u,s){
 const p=visitPatternState(s),done=p.ribbons>=6,needsHelp=!visitAnyMove(p.board);
 return `<section class="visit-pattern-game"><h2>${done?'Праздничные наряды готовы!':'Соберём узор для нарядов'}</h2><p>Выбери фигуру и нажми на клетку, где будет её левый верхний угол. Заполни целую строку или столбец — блоки исчезнут, а наряд получит узорную полосу. Нужно шесть полос!</p><div class="visit-pattern-progress"><span>${p.ribbons} из 6 полос</span><div class="visit-ribbons" aria-label="Собрано ${p.ribbons} из шести полос">${Array.from({length:6},(_,i)=>`<i class="${p.ribbons>i?'earned':''}">${p.ribbons>i?kidIcon('check'):''}</i>`).join('')}</div></div><div class="visit-pattern-layout"><section class="visit-block-game game-panel"><div class="visit-pattern-board" role="grid" aria-label="Поле узоров, восемь строк и восемь столбцов">${p.board.map((v,i)=>`<button type="button" role="gridcell" class="${v?'filled':'empty'} ${p.lastCleared?.includes(i)?'just-cleared':''}" style="--tile:${['transparent','#91ad8a','#d7b36a','#bc9583','#8eaeb1'][v]}" data-v-cell="${i}" tabindex="${i===0?'0':'-1'}" aria-label="Строка ${Math.floor(i/8)+1}, столбец ${i%8+1}, ${v?'занято':'свободно'}" ${done?'disabled':''}></button>`).join('')}</div><div class="visit-shape-tray" role="group" aria-label="Выбери фигуру">${[['domino','Два блока'],['line','Три блока'],['square','Квадрат'],['corner','Уголок']].map(([id,name])=>`<button type="button" class="btn secondary ${p.selected===id?'selected':''}" data-v-shape="${id}" aria-pressed="${p.selected===id}" ${done?'disabled':''}>${visitShapeArt(id,p.selected===id?p.rotation:0)}<span>${name}</span></button>`).join('')}</div><div class="visit-pattern-controls"><button type="button" class="btn secondary" data-v-rotate ${done?'disabled':''}>Повернуть фигуру ↻</button>${needsHelp&&!done?'<button type="button" class="kid-primary" data-v-rescue>Освободить поле</button>':''}</div><p class="visit-game-feedback" id="visitPatternFeedback" tabindex="-1" role="status" aria-live="polite">${esc(p.feedback||(done?'Ты собрал все шесть полос. Можно идти дальше!':needsHelp?'Фигурам тесно. Освободим поле — все заработанные полосы останутся.':'Подсказка: начни фигурой «Два блока» и заполни пробелы в строках.'))}</p></section><aside class="visit-outfit-preview game-panel"><h3>Мастерская Данияра</h3><div class="visit-pattern-outfits">${[0,1].map(i=>`<div>${visitPatternCostume(i,p.ribbons)}<strong>${i===0?'Первый наряд':'Второй наряд'}</strong><span>${Math.min(3,Math.max(0,p.ribbons-i*3))} / 3 полосы</span></div>`).join('')}</div><p>Каждая собранная линия превращается в новую полосу. Эти геометрические мотивы придуманы для игры; мы не приписываем им историческое значение.</p></aside></div></section>`;
}
function wireVisitPatterns(u,s,redraw){
 const root=document.querySelector('.visit-pattern-game');if(!root)return;
 const update=(focus)=>redraw(focus||'#visitPatternFeedback');
 root.querySelectorAll('[data-v-shape]').forEach(b=>b.onclick=()=>{const p=visitPatternState(s);p.selected=b.dataset.vShape;p.rotation=0;p.feedback='Фигура выбрана. Нажми на свободную клетку для её левого верхнего угла.';update('[data-v-shape="'+p.selected+'"]')});
 root.querySelector('[data-v-rotate]')?.addEventListener('click',()=>{const p=visitPatternState(s);p.rotation=(p.rotation+1)%4;p.feedback='Фигура повёрнута. Теперь выбери место на поле.';update('[data-v-rotate]')});
 root.querySelector('[data-v-rescue]')?.addEventListener('click',()=>{const p=visitPatternState(s);p.board=visitPatternBoard();p.lastCleared=[];p.feedback='Готово! Новые пробелы ждут фигур. Все твои полосы сохранены.';p.rescues=(Number(p.rescues)||0)+1;update()});
 root.querySelectorAll('[data-v-cell]').forEach(b=>{
  b.onclick=()=>{const p=visitPatternState(s);if(p.ribbons>=6)return;const index=+b.dataset.vCell,row=Math.floor(index/8),col=index%8,cells=visitShapeCells(p.selected,p.rotation);if(!visitCanPlace(p.board,cells,row,col)){visitGameError(u,'patterns','blocked-placement');p.feedback='Здесь фигура не помещается. Выбери свободное место или поверни её. Полосы не теряются.';update('[data-v-cell="'+index+'"]');return}for(const [dy,dx]of cells)p.board[(row+dy)*8+col+dx]=(p.moves%3)+1;p.moves++;const rows=[],cols=[];for(let i=0;i<8;i++){if(Array.from({length:8},(_,j)=>p.board[i*8+j]).every(Boolean))rows.push(i);if(Array.from({length:8},(_,j)=>p.board[j*8+i]).every(Boolean))cols.push(i)}const clear=new Set();rows.forEach(r=>{for(let c=0;c<8;c++)clear.add(r*8+c)});cols.forEach(c=>{for(let r=0;r<8;r++)clear.add(r*8+c)});p.lastCleared=[...clear];clear.forEach(i=>p.board[i]=0);const earned=rows.length+cols.length;p.ribbons=Math.min(6,p.ribbons+earned);p.feedback=earned?'Линия собрана! '+(p.ribbons>=6?'Оба наряда готовы. Ты настоящий мастер узоров!':'Новая полоса украсила наряд. Продолжай!'):'Фигура на месте. Заполни строку или столбец целиком.';if(!visitAnyMove(p.board)&&p.ribbons<6)p.feedback+=' Больше нет места? Нажми «Освободить поле» — полосы останутся.';visitPatternState(s);update(earned?'#visitPatternFeedback':'[data-v-cell="'+index+'"]')};
  b.onkeydown=e=>{const index=+b.dataset.vCell,offset={ArrowLeft:-1,ArrowRight:1,ArrowUp:-8,ArrowDown:8}[e.key];if(offset===undefined)return;e.preventDefault();const target=index+offset;if(target<0||target>63||(e.key==='ArrowLeft'&&index%8===0)||(e.key==='ArrowRight'&&index%8===7))return;root.querySelectorAll('[data-v-cell]').forEach(c=>c.tabIndex=-1);const next=root.querySelector('[data-v-cell="'+target+'"]');if(next){next.tabIndex=0;next.focus()}};
 });
}
